'use strict'

const {
  parseCacheControlHeader,
  hasInvalidCacheControlDirective
} = require('../../../../lib/util/cache')

describe('parseCacheControlHeader', () => {
  describe('empty and trivial input', () => {
    test('returns an empty object for an empty header', () => {
      expect(parseCacheControlHeader('')).toEqual({})
    })

    test('returns an empty object for a header that is only separators and whitespace', () => {
      expect(parseCacheControlHeader(',,,')).toEqual({})
      expect(parseCacheControlHeader('   ')).toEqual({})
    })

    test('returns a fresh object for every call', () => {
      const first = parseCacheControlHeader('max-age=10')
      const second = parseCacheControlHeader('max-age=10')

      expect(first).not.toBe(second)
      expect(first).toEqual({ 'max-age': 10 })
      expect(second).toEqual({ 'max-age': 10 })
    })
  })

  describe('numeric delta-seconds directives', () => {
    test.each([
      ['max-age=100', { 'max-age': 100 }],
      ['min-fresh=30', { 'min-fresh': 30 }],
      ['max-stale=45', { 'max-stale': 45 }],
      ['s-maxage=60', { 's-maxage': 60 }],
      ['stale-while-revalidate=15', { 'stale-while-revalidate': 15 }],
      ['stale-if-error=25', { 'stale-if-error': 25 }]
    ])('parses %s', (header, expected) => {
      expect(parseCacheControlHeader(header)).toEqual(expected)
    })

    test('accepts zero as a valid delta', () => {
      expect(parseCacheControlHeader('max-age=0')).toEqual({ 'max-age': 0 })
    })

    test('accepts values with leading zeros', () => {
      expect(parseCacheControlHeader('max-age=000100')).toEqual({ 'max-age': 100 })
    })

    test('accepts a quoted numeric value', () => {
      expect(parseCacheControlHeader('max-age="100"')).toEqual({ 'max-age': 100 })
    })

    test('clamps values to the maximum delta of 2147483647', () => {
      expect(parseCacheControlHeader('max-age=99999999999')).toEqual({ 'max-age': 2147483647 })
      expect(parseCacheControlHeader('min-fresh=99999999999')).toEqual({ 'min-fresh': 2147483647 })
    })

    test('is case insensitive for directive names', () => {
      expect(parseCacheControlHeader('MAX-AGE=100')).toEqual({ 'max-age': 100 })
      expect(parseCacheControlHeader('Max-Age="100"')).toEqual({ 'max-age': 100 })
    })

    test('keeps the smallest value when a directive repeats', () => {
      expect(parseCacheControlHeader('max-age=100, max-age=50')).toEqual({ 'max-age': 50 })
      expect(parseCacheControlHeader('max-age=50, max-age=100')).toEqual({ 'max-age': 50 })
      expect(parseCacheControlHeader('max-stale=10, max-stale=5')).toEqual({ 'max-stale': 5 })
      expect(parseCacheControlHeader('s-maxage=10, s-maxage=5')).toEqual({ 's-maxage': 5 })
    })

    test('keeps the largest value for min-fresh when it repeats', () => {
      expect(parseCacheControlHeader('min-fresh=10, min-fresh=20')).toEqual({ 'min-fresh': 20 })
      expect(parseCacheControlHeader('min-fresh=20, min-fresh=10')).toEqual({ 'min-fresh': 20 })
    })

    test('parses several different numeric directives in one header', () => {
      const header = 'max-age=100, stale-while-revalidate=10, stale-if-error=20, s-maxage=5, max-stale=15'

      expect(parseCacheControlHeader(header)).toEqual({
        'max-age': 100,
        'stale-while-revalidate': 10,
        'stale-if-error': 20,
        's-maxage': 5,
        'max-stale': 15
      })
    })

    test.each([
      ['max-age=abc', 'max-age'],
      ['max-age=1.5', 'max-age'],
      ['max-age=+100', 'max-age'],
      ['max-age=-100', 'max-age'],
      ['max-age=', 'max-age'],
      ['max-age', 'max-age'],
      ['min-fresh', 'min-fresh'],
      ['stale-while-revalidate=abc', 'stale-while-revalidate']
    ])('ignores the invalid numeric directive in %s and records it as invalid', (header, key) => {
      const directives = parseCacheControlHeader(header)

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, key)).toBe(true)
    })

    test('rejects a quoted value that only partially looks numeric', () => {
      const directives = parseCacheControlHeader('max-age=" 100"')

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

    test('rejects whitespace around the delimiter of a numeric directive', () => {
      expect(parseCacheControlHeader('max-age =100')).toEqual({})
      expect(parseCacheControlHeader('max-age= 100')).toEqual({})
      expect(parseCacheControlHeader('max-age\t=100')).toEqual({})
    })

    test('drops a previously parsed value when a later occurrence is invalid', () => {
      const directives = parseCacheControlHeader('max-age=100, max-age=abc')

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

    test('ignores subsequent occurrences after an invalid one', () => {
      const directives = parseCacheControlHeader('max-age=abc, max-age=100')

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

