      expect(parseCacheControlHeader('s-maxage=10, s-maxage=5')).toEqual({ 's-maxage': 5 })
    })

    test('keeps the largest value for min-fresh when it repeats', () => {
      expect(parseCacheControlHeader('min-fresh=10, min-fresh=20')).toEqual({ 'min-fresh': 20 })
      expect(parseCacheControlHeader('min-fresh=20, min-fresh=10')).toEqual({ 'min-fresh': 20 })
    })

    test('parses several different numeric directives in one header', () => {
      const header = 'max-age=100, stale-while-revalidate=10, stale-if-error=20, s-maxage=5, max-stale=15'

      expect(parseCacheControlHeader(header)).toEqual({
        'max-age': 100,
        'stale-while-revalidate': 10,
        'stale-if-error': 20,
        's-maxage': 5,
        'max-stale': 15
      })
    })

    test.each([
      ['max-age=abc', 'max-age'],
      ['max-age=1.5', 'max-age'],
      ['max-age=+100', 'max-age'],
      ['max-age=-100', 'max-age'],
      ['max-age=', 'max-age'],
      ['max-age', 'max-age'],
      ['min-fresh', 'min-fresh'],
      ['stale-while-revalidate=abc', 'stale-while-revalidate']
    ])('ignores the invalid numeric directive in %s and records it as invalid', (header, key) => {
      const directives = parseCacheControlHeader(header)

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, key)).toBe(true)
    })

    test('rejects a quoted value that only partially looks numeric', () => {
      const directives = parseCacheControlHeader('max-age=" 100"')

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

    test('rejects whitespace around the delimiter of a numeric directive', () => {
      expect(parseCacheControlHeader('max-age =100')).toEqual({})
      expect(parseCacheControlHeader('max-age= 100')).toEqual({})
      expect(parseCacheControlHeader('max-age\t=100')).toEqual({})
    })

    test('drops a previously parsed value when a later occurrence is invalid', () => {
      const directives = parseCacheControlHeader('max-age=100, max-age=abc')

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

    test('ignores subsequent occurrences after an invalid one', () => {
      const directives = parseCacheControlHeader('max-age=abc, max-age=100')

      expect(directives).toEqual({})
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

    test('does not let the invalidation of one directive affect another', () => {
      const directives = parseCacheControlHeader('max-age=abc, no-cache=foo, min-fresh=10')

      expect(directives).toEqual({ 'no-cache': ['foo'], 'min-fresh': 10 })
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
      expect(hasInvalidCacheControlDirective(directives, 'min-fresh')).toBe(false)
    })

    test('does not mark a valid numeric directive as invalid', () => {
      const directives = parseCacheControlHeader('max-age=10')

      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(false)
    })
  })

  describe('private and no-cache directives', () => {
    test('parses unqualified directives as true', () => {
      expect(parseCacheControlHeader('no-cache')).toEqual({ 'no-cache': true })
      expect(parseCacheControlHeader('private')).toEqual({ private: true })
      expect(parseCacheControlHeader('NO-CACHE')).toEqual({ 'no-cache': true })
    })

    test('parses a directive with an empty value as true', () => {
      expect(parseCacheControlHeader('no-cache=')).toEqual({ 'no-cache': true })
      expect(parseCacheControlHeader('private=')).toEqual({ private: true })
      expect(parseCacheControlHeader('no-cache= ')).toEqual({ 'no-cache': true })
    })

    test('parses a single unquoted field name into an array', () => {
      expect(parseCacheControlHeader('no-cache=foo')).toEqual({ 'no-cache': ['foo'] })
      expect(parseCacheControlHeader('private=set-cookie')).toEqual({ private: ['set-cookie'] })
    })

    test('parses a single quoted field name into an array', () => {
      expect(parseCacheControlHeader('no-cache="foo"')).toEqual({ 'no-cache': ['foo'] })
      expect(parseCacheControlHeader('no-cache=""')).toEqual({ 'no-cache': true })
    })

    test('parses a quoted comma separated field list', () => {
      expect(parseCacheControlHeader('no-cache="foo, bar"')).toEqual({ 'no-cache': ['foo', 'bar'] })
      expect(parseCacheControlHeader('private="set-cookie, authorization"')).toEqual({
        private: ['set-cookie', 'authorization']
      })
    })

    test('continues parsing after a quoted field list', () => {
      expect(parseCacheControlHeader('no-cache="foo, bar", max-age=10')).toEqual({
        'no-cache': ['foo', 'bar'],
        'max-age': 10
      })
    })

    test('trims optional whitespace around field names', () => {
      expect(parseCacheControlHeader('no-cache="  foo  "')).toEqual({ 'no-cache': ['foo'] })
      expect(parseCacheControlHeader('no-cache="foo,   bar"')).toEqual({ 'no-cache': ['foo', 'bar'] })
    })

    test('lower cases field names', () => {
      expect(parseCacheControlHeader('no-cache="Set-Cookie"')).toEqual({ 'no-cache': ['set-cookie'] })
      expect(parseCacheControlHeader('no-cache="set-cookie,Authorization"')).toEqual({
        'no-cache': ['set-cookie', 'authorization']
      })
    })

    test('concatenates field names from repeated qualified directives', () => {
      expect(parseCacheControlHeader('no-cache=foo, no-cache=bar')).toEqual({
        'no-cache': ['foo', 'bar']
      })
      expect(parseCacheControlHeader('no-cache="a, b", no-cache="c"')).toEqual({
        'no-cache': ['a', 'b', 'c']
      })
    })

    test('treats the directive as true when it appears both qualified and unqualified', () => {
      expect(parseCacheControlHeader('no-cache=foo, no-cache')).toEqual({ 'no-cache': true })
      expect(parseCacheControlHeader('no-cache, no-cache=foo')).toEqual({ 'no-cache': true })
      expect(parseCacheControlHeader('no-cache="a", no-cache="b", no-cache')).toEqual({ 'no-cache': true })
    })

    test('treats the directive as true when a field name is not a valid token', () => {
      expect(parseCacheControlHeader('no-cache="foo bar"')).toEqual({ 'no-cache': true })
      expect(parseCacheControlHeader('no-cache=foo/bar')).toEqual({ 'no-cache': true })
      expect(parseCacheControlHeader('no-cache=","')).toEqual({ 'no-cache': true })
    })

    test('treats the directive as true when the quoted list is unterminated', () => {
      expect(parseCacheControlHeader('no-cache="a, b')).toEqual({ 'no-cache': true })
    })
  })

  describe('directives that must not have an argument', () => {
    test.each([
      ['public', 'public'],
      ['must-revalidate', 'must-revalidate'],
      ['proxy-revalidate', 'proxy-revalidate'],
      ['immutable', 'immutable'],
      ['no-transform', 'no-transform'],
      ['must-understand', 'must-understand'],
      ['only-if-cached', 'only-if-cached']
    ])('parses %s as true', (header, key) => {
      expect(parseCacheControlHeader(header)).toEqual({ [key]: true })
    })

    test('is case insensitive for directive names', () => {
      expect(parseCacheControlHeader('PUBLIC')).toEqual({ public: true })
    })

    test.each(['public=1', 'immutable=yes', 'only-if-cached=""'])(
      'ignores the malformed qualified directive in %s',
      (header) => {
        expect(parseCacheControlHeader(header)).toEqual({})
      }
    )

    test('removes an earlier occurrence when a later one is qualified', () => {
      expect(parseCacheControlHeader('public, public=1')).toEqual({})
    })

    test('ignores later occurrences once the directive was malformed', () => {
      expect(parseCacheControlHeader('public=1, public')).toEqual({})
      expect(parseCacheControlHeader('public=1, public=2, public')).toEqual({})
    })

    test('does not affect valid directives that follow', () => {
      expect(parseCacheControlHeader('public=1, max-age=5')).toEqual({ 'max-age': 5 })
    })
  })

