    test('parses no-store as true', () => {
      expect(parseCacheControlHeader('no-store')).toEqual({ 'no-store': true })
      expect(parseCacheControlHeader('NO-STORE')).toEqual({ 'no-store': true })
    })

    test('ignores an argument given to no-store', () => {
      expect(parseCacheControlHeader('no-store=1')).toEqual({ 'no-store': true })
    })
  })

