    test('ignores unknown directives', () => {
      expect(parseCacheControlHeader('unknown-directive=1')).toEqual({})
      expect(parseCacheControlHeader('Vary')).toEqual({})
    })

    test('keeps parsing known directives around unknown ones', () => {
      expect(parseCacheControlHeader('foo, max-age=10, bar=baz, no-store')).toEqual({
        'max-age': 10,
