      const directives = parseCacheControlHeader('max-age="10", max-age=5')

      expect(directives).toEqual({ 'max-age': 5 })
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(false)
    })
  })

  describe('array input', () => {
    test('joins array values before parsing', () => {
      expect(parseCacheControlHeader(['max-age=10', 'no-cache'])).toEqual({
        'max-age': 10,
        'no-cache': true
      })
    })

    test('joins array values that contain quoted field lists', () => {
      expect(parseCacheControlHeader(['no-cache="a, b"', 'max-age=5'])).toEqual({
        'no-cache': ['a', 'b'],
        'max-age': 5
      })
    })

    test('applies the numeric merging rules across array entries', () => {
      expect(parseCacheControlHeader(['max-age=10', 'max-age=20'])).toEqual({ 'max-age': 10 })
      expect(parseCacheControlHeader(['min-fresh=10', 'min-fresh=20'])).toEqual({ 'min-fresh': 20 })
    })
  })

  describe('combined realistic headers', () => {
    test('parses a full cache-control response header', () => {
      const header = 'private, no-cache="Set-Cookie", max-age=100, s-maxage=50, must-revalidate, no-transform'

      expect(parseCacheControlHeader(header)).toEqual({
        private: true,
        'no-cache': ['set-cookie'],
        'max-age': 100,
        's-maxage': 50,
        'must-revalidate': true,
        'no-transform': true
      })
    })

    test('parses every supported no-argument directive in one header', () => {
      const header = 'public, immutable, only-if-cached, must-understand, proxy-revalidate, ' +
        'must-revalidate, no-transform, no-store, no-cache, private'

      expect(parseCacheControlHeader(header)).toEqual({
        public: true,
        immutable: true,
        'only-if-cached': true,
        'must-understand': true,
        'proxy-revalidate': true,
        'must-revalidate': true,
        'no-transform': true,
        'no-store': true,
        'no-cache': true,
        private: true
      })
    })

    test('keeps a valid directive while another one is invalid', () => {
      const directives = parseCacheControlHeader('no-cache, no-store, max-age=abc')

      expect(directives).toEqual({ 'no-cache': true, 'no-store': true })
      expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    })

    test('handles a quoted field list appearing between numeric directives', () => {
      expect(parseCacheControlHeader('max-age=5, no-cache="a, b", max-age=9')).toEqual({
        'max-age': 5,
        'no-cache': ['a', 'b']
      })
    })
  })
})
