      expect(feed(parser, Buffer.from([0x81]))).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const callback = feed(parser, Buffer.from([0x02, 0x68, 0x69]))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledWith(opcodes.TEXT, Buffer.from('hi'))
    })
  })

  describe('data frames', () => {
    it('delivers a text frame with a short payload', () => {
      const { handler, parser } = createParser()

      const callback = feed(parser, buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('hello') }))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)

      const [opcode, data] = handler.onMessage.mock.calls[0]
      expect(opcode).toBe(opcodes.TEXT)
      expect(Buffer.isBuffer(data)).toBe(true)
      expect(data.toString()).toBe('hello')
    })

    it('delivers a binary frame', () => {
