  })

  describe('fragmentation', () => {
    it('reassembles a fragmented text message', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('hello ') }))
      expect(handler.onMessage).not.toHaveBeenCalled()

      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, fin: false, payload: Buffer.from('frag') }))
      expect(handler.onMessage).not.toHaveBeenCalled()

      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('mented') }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.TEXT)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('hello fragmented')
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })

    it('reassembles fragments that arrive in separate chunks', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.BINARY, fin: false, payload: Buffer.from([0x01, 0x02]) }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from([0x03, 0x04]) }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.BINARY)
      expect([...handler.onMessage.mock.calls[0][1]]).toEqual([0x01, 0x02, 0x03, 0x04])
