      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('a') }))
      feed(parser, buildFrame({ opcode: opcodes.PING, payload: Buffer.from('ping') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('b') }))

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('ab')
    })

    it('fails with 1008 when the fragment limit is reached', () => {
      const { handler, parser } = createParser({ maxFragments: 2 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('a') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, fin: false, payload: Buffer.from('b') }))
      expect(handler.controller.abort).not.toHaveBeenCalled()

      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('c') }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1008)
      expect(frames[0].payload.subarray(2).toString()).toBe('Too many message fragments')
    })

    it('accepts exactly the maximum number of fragments', () => {
      const { handler, parser } = createParser({ maxFragments: 3 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('a') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, fin: false, payload: Buffer.from('b') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('c') }))

      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('abc')
