      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1009)
      expect(frames[0].payload.subarray(2).toString()).toBe('Payload size exceeds maximum allowed size')
    })

    it('accepts a payload of exactly the maximum size', () => {
      const { handler, parser } = createParser({ maxPayloadSize: 5 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('abcde') }))

      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('abcde')
    })

    it('applies the limit to the 16 bit length state as well', () => {
      const { handler, parser } = createParser({ maxPayloadSize: 10 })

      feed(parser, buildFrame({ opcode: opcodes.BINARY, payload: Buffer.alloc(200) }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()
      expect(closeFramesWrittenTo(handler)[0].payload.readUInt16BE(0)).toBe(1009)
    })

    it('disables the limit when maxPayloadSize is 0', () => {
