      const payload = Buffer.alloc(1000, 0x7a)

      feed(parser, buildFrame({ opcode: opcodes.BINARY, payload }))

      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].length).toBe(1000)
    })
