  describe('control frames', () => {
    it('replies to a PING with a PONG carrying the same payload', () => {
      const { handler, parser } = createParser()

      const callback = feed(parser, buildFrame({ opcode: opcodes.PING, payload: Buffer.from('ping!') }))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onPing.mock.calls[0][0].toString()).toBe('ping!')

      expect(handler.socket.write).toHaveBeenCalledTimes(1)
      const written = decodeWrittenFrame(handler.socket.chunks[0])
      expect(written.opcode).toBe(opcodes.PONG)
      expect(written.payload.toString()).toBe('ping!')
    })

    it('does not reply to a PING once a close frame has been received', () => {
      const handler = createHandler()
      handler.closeState.add(2 /* RECEIVED */)
      const parser = new ByteParser(handler, null)

      feed(parser, buildFrame({ opcode: opcodes.PING, payload: Buffer.from('ping') }))

      expect(handler.socket.write).not.toHaveBeenCalled()
      expect(handler.onPing).not.toHaveBeenCalled()
      expect(handler.controller.abort).not.toHaveBeenCalled()
