    it('forwards unsolicited PONG frames without writing to the socket', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.PONG, payload: Buffer.from('pong') }))

      expect(handler.onPong).toHaveBeenCalledTimes(1)
      expect(handler.onPong.mock.calls[0][0].toString()).toBe('pong')
      expect(handler.socket.write).not.toHaveBeenCalled()
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })

    it('continues parsing data frames after a control frame in the same chunk', () => {
      const { handler, parser } = createParser()

      feed(parser, Buffer.concat([
        buildFrame({ opcode: opcodes.PING, payload: Buffer.from('p') }),
        buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('after') })
      ]))

