      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('after')
    })

    it('handles a close frame, replies to it and exposes the closing info', () => {
      const { handler, parser } = createParser()
      const closePayload = Buffer.alloc(2 + 3)
      closePayload.writeUInt16BE(1000, 0)
      closePayload.write('bye', 2)

      feed(parser, buildFrame({ opcode: opcodes.CLOSE, payload: closePayload }))

      expect(handler.readyState).toBe(states.CLOSING)
      expect(handler.closeState.has(1 /* SENT */)).toBe(true)
      expect(handler.closeState.has(2 /* RECEIVED */)).toBe(true)
      expect(parser.closingInfo).toEqual({ code: 1000, reason: 'bye', error: false })

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1000)

