      const handler = createHandler()
      handler.socket.writableNeedDrain = true
      const parser = new ByteParser(handler, null)

      const pingFrame = buildFrame({ opcode: opcodes.PING, payload: Buffer.from('p') })
      const callback = feed(parser, Buffer.concat([pingFrame, pingFrame]))

      expect(handler.onPing).toHaveBeenCalledTimes(1)

      parser.destroyed = true
      handler.socket.emit('drain')

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(callback).not.toHaveBeenCalled()
    })
  })

  describe('permessage-deflate', () => {
    function compressedExtensions () {
      return new Map([['permessage-deflate', '']])
    }

    it('decompresses a compressed text message', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.from('compressed payload'))

