      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('compressed payload')
      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(callback).toHaveBeenCalled()
    })

    it('decompresses an uncompressed frame when the extension is negotiated but RSV1 is clear', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())

      const callback = feed(parser, buildFrame({
        opcode: opcodes.TEXT,
        rsv1: false,
        payload: Buffer.from('plain payload')
      }))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('plain payload')
    })

    it('fails with 1007 when the compressed payload cannot be inflated', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())
      const garbage = Buffer.from([0xff, 0xff, 0xff, 0xff, 0xff, 0xff])

      feed(parser, buildFrame({ opcode: opcodes.TEXT, rsv1: true, payload: garbage }))

