    })

    it('fails with 1009 when the decompressed message exceeds the payload limit', async () => {
      const { handler, parser } = createParser({ maxPayloadSize: 100 }, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x41))
      expect(compressed.length).toBeLessThanOrEqual(100)

      feed(parser, buildFrame({ opcode: opcodes.TEXT, rsv1: true, payload: compressed }))

      await nextTick()

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1009)
      expect(frames[0].payload.subarray(2).toString()).toBe('Max decompressed message size exceeded')
    })

    it('decompresses large payloads when the payload limit is disabled', async () => {
      const { handler, parser } = createParser({ maxPayloadSize: 0 }, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x41))

      feed(parser, buildFrame({ opcode: opcodes.BINARY, rsv1: true, payload: compressed }))

      await nextTick()

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.BINARY)
