'use strict'

const { EventEmitter } = require('node:events')
const zlib = require('node:zlib')

const { ByteParser } = require('../../../../../lib/web/websocket/receiver')
const { states, opcodes } = require('../../../../../lib/web/websocket/constants')

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

/**
 * Creates a fake duplex socket. `write()` records every buffer the parser
 * hands to the transport so that closing handshake replies can be inspected.
 */
function createSocket () {
  const socket = new EventEmitter()

  socket.destroyed = false
  socket.writableNeedDrain = false
  socket.chunks = []
  socket.write = jest.fn((chunk) => {
    socket.chunks.push(chunk)
    return true
  })
  socket.destroy = jest.fn(() => {
    socket.destroyed = true
  })

  return socket
}

/**
 * Minimal stand-in for `import('./websocket').Handler`.
 */
function createHandler (overrides = {}) {
  const socket = createSocket()

  const handler = {
    readyState: states.OPEN,
    socket,
    closeState: new Set(),
    controller: { abort: jest.fn() },
    onMessage: jest.fn(),
    onPing: jest.fn(),
    onPong: jest.fn(),
    onSocketClose: jest.fn(),
    ...overrides
  }

  return handler
}

/**
 * Builds a single websocket frame. `length` overrides the encoded payload
 * length so that malformed frames can be produced.
 */
function buildFrame ({
  fin = true,
  opcode = opcodes.TEXT,
  payload = Buffer.alloc(0),
  rsv1 = false,
  rsv2 = false,
  rsv3 = false,
  masked = false,
  length = null
} = {}) {
  const firstByte =
    (fin ? 0x80 : 0x00) |
    (rsv1 ? 0x40 : 0x00) |
    (rsv2 ? 0x20 : 0x00) |
    (rsv3 ? 0x10 : 0x00) |
    (opcode & 0x0f)

  const encodedLength = length ?? payload.length
  const maskBit = masked ? 0x80 : 0x00

  let header

  if (encodedLength < 126) {
    header = Buffer.from([firstByte, maskBit | encodedLength])
  } else if (encodedLength < 2 ** 16) {
    header = Buffer.alloc(4)
    header[0] = firstByte
    header[1] = maskBit | 126
    header.writeUInt16BE(encodedLength, 2)
  } else {
    header = Buffer.alloc(10)
    header[0] = firstByte
    header[1] = maskBit | 127
    header.writeUInt32BE(Math.floor(encodedLength / 2 ** 32), 2)
    header.writeUInt32BE(encodedLength % 2 ** 32, 6)
  }

  return Buffer.concat([header, payload])
}

/**
 * Builds a frame with an explicit 64 bit payload length field.
 */
function buildFrame64 ({ upper = 0, lower = 0, payload = Buffer.alloc(0), fin = true, opcode = opcodes.TEXT } = {}) {
  const header = Buffer.alloc(10)
  header[0] = (fin ? 0x80 : 0x00) | (opcode & 0x0f)
  header[1] = 127
  header.writeUInt32BE(upper, 2)
  header.writeUInt32BE(lower, 6)
  return Buffer.concat([header, payload])
}

/**
 * Decodes a frame the parser wrote to the socket. Client frames are masked,
 * so the payload has to be unmasked before it can be inspected.
 */
function decodeWrittenFrame (frame) {
  const opcode = frame[0] & 0x0f
  const masked = (frame[1] & 0x80) === 0x80
  const length = frame[1] & 0x7f

  let offset = 2
  let payload

  if (masked) {
    const mask = frame.subarray(offset, offset + 4)
    offset += 4
    payload = Buffer.from(frame.subarray(offset, offset + length))
    for (let i = 0; i < payload.length; i++) {
      payload[i] ^= mask[i % 4]
    }
  } else {
    payload = frame.subarray(offset, offset + length)
  }

  return { opcode, masked, payload }
}

function closeFramesWrittenTo (handler) {
  return handler.socket.chunks
    .map(decodeWrittenFrame)
    .filter(({ opcode }) => opcode === opcodes.CLOSE)
}

/**
 * Drives a single chunk through the parser and returns the callback spy that
 * the parser was handed (the `callback` of `run(callback)`).
 */
function feed (parser, chunk) {
  const callback = jest.fn()
  parser._write(chunk, null, callback)
  return callback
}

function createParser (options, extensions) {
  const handler = createHandler(options && options.handlerOverrides)
  const parser = new ByteParser(handler, extensions === undefined ? null : extensions, options)
  return { handler, parser }
}

const nextTick = () => new Promise((resolve) => setTimeout(resolve, 50))

