describe('ByteParser run()', () => {
  describe('when the header is not complete yet', () => {
    it('invokes the callback without consuming the pending byte', () => {
      const { handler, parser } = createParser()

      const callback = feed(parser, Buffer.from([0x81]))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()
      expect(handler.socket.write).not.toHaveBeenCalled()
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })

    it('invokes the callback when no bytes at all are buffered', () => {
      const { handler, parser } = createParser()

      const callback = feed(parser, Buffer.alloc(0))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()
    })

    it('resumes parsing once the remaining header and payload arrive', () => {
      const { handler, parser } = createParser()

      expect(feed(parser, Buffer.from([0x81]))).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const callback = feed(parser, Buffer.from([0x02, 0x68, 0x69]))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledWith(opcodes.TEXT, Buffer.from('hi'))
