      expect(frames[0].payload.readUInt16BE(0)).toBe(1002)
      expect(frames[0].payload.subarray(2).toString()).toBe('Expected continuation frame')
    })

    it('stops parsing the remaining bytes of the chunk after a violation', () => {
      const { handler, parser } = createParser()

      const chunk = Buffer.concat([
        Buffer.from([0x83, 0x00]),
        buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('ignored') })
      ])

      feed(parser, chunk)

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()
    })

    it('reports the connection through onSocketClose when not yet established', () => {
      const handler = createHandler({ readyState: states.CONNECTING })
      const parser = new ByteParser(handler, null)

      feed(parser, Buffer.from([0x83, 0x00]))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onSocketClose).toHaveBeenCalledTimes(1)
      expect(handler.socket.destroy).not.toHaveBeenCalled()
      expect(closeFramesWrittenTo(handler)).toHaveLength(0)
    })
  })

  describe('fragmentation', () => {
    it('reassembles a fragmented text message', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('hello ') }))
      expect(handler.onMessage).not.toHaveBeenCalled()

      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, fin: false, payload: Buffer.from('frag') }))
      expect(handler.onMessage).not.toHaveBeenCalled()

      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('mented') }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.TEXT)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('hello fragmented')
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })

    it('reassembles fragments that arrive in separate chunks', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.BINARY, fin: false, payload: Buffer.from([0x01, 0x02]) }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from([0x03, 0x04]) }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.BINARY)
      expect([...handler.onMessage.mock.calls[0][1]]).toEqual([0x01, 0x02, 0x03, 0x04])
    })

    it('allows a fragmented message to interleave with control frames', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('a') }))
      feed(parser, buildFrame({ opcode: opcodes.PING, payload: Buffer.from('ping') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('b') }))

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('ab')
    })

    it('fails with 1008 when the fragment limit is reached', () => {
      const { handler, parser } = createParser({ maxFragments: 2 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('a') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, fin: false, payload: Buffer.from('b') }))
      expect(handler.controller.abort).not.toHaveBeenCalled()

      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('c') }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1008)
      expect(frames[0].payload.subarray(2).toString()).toBe('Too many message fragments')
    })

    it('accepts exactly the maximum number of fragments', () => {
      const { handler, parser } = createParser({ maxFragments: 3 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, fin: false, payload: Buffer.from('a') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, fin: false, payload: Buffer.from('b') }))
      feed(parser, buildFrame({ opcode: opcodes.CONTINUATION, payload: Buffer.from('c') }))

      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('abc')
    })
  })

  describe('maximum payload size', () => {
    it('fails with 1009 when a declared payload exceeds the limit', () => {
      const { handler, parser } = createParser({ maxPayloadSize: 4 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('abcde') }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1009)
      expect(frames[0].payload.subarray(2).toString()).toBe('Payload size exceeds maximum allowed size')
    })

    it('accepts a payload of exactly the maximum size', () => {
      const { handler, parser } = createParser({ maxPayloadSize: 5 })

      feed(parser, buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('abcde') }))

      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('abcde')
    })

    it('applies the limit to the 16 bit length state as well', () => {
      const { handler, parser } = createParser({ maxPayloadSize: 10 })

      feed(parser, buildFrame({ opcode: opcodes.BINARY, payload: Buffer.alloc(200) }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()
      expect(closeFramesWrittenTo(handler)[0].payload.readUInt16BE(0)).toBe(1009)
    })

    it('disables the limit when maxPayloadSize is 0', () => {
      const { handler, parser } = createParser({ maxPayloadSize: 0 })
      const payload = Buffer.alloc(1000, 0x7a)

      feed(parser, buildFrame({ opcode: opcodes.BINARY, payload }))

      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].length).toBe(1000)
    })
  })

  describe('control frames', () => {
    it('replies to a PING with a PONG carrying the same payload', () => {
      const { handler, parser } = createParser()

      const callback = feed(parser, buildFrame({ opcode: opcodes.PING, payload: Buffer.from('ping!') }))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onPing.mock.calls[0][0].toString()).toBe('ping!')

      expect(handler.socket.write).toHaveBeenCalledTimes(1)
      const written = decodeWrittenFrame(handler.socket.chunks[0])
      expect(written.opcode).toBe(opcodes.PONG)
      expect(written.payload.toString()).toBe('ping!')
    })

    it('does not reply to a PING once a close frame has been received', () => {
      const handler = createHandler()
      handler.closeState.add(2 /* RECEIVED */)
      const parser = new ByteParser(handler, null)

      feed(parser, buildFrame({ opcode: opcodes.PING, payload: Buffer.from('ping') }))

      expect(handler.socket.write).not.toHaveBeenCalled()
      expect(handler.onPing).not.toHaveBeenCalled()
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })

    it('forwards unsolicited PONG frames without writing to the socket', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.PONG, payload: Buffer.from('pong') }))

      expect(handler.onPong).toHaveBeenCalledTimes(1)
      expect(handler.onPong.mock.calls[0][0].toString()).toBe('pong')
      expect(handler.socket.write).not.toHaveBeenCalled()
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })

    it('continues parsing data frames after a control frame in the same chunk', () => {
      const { handler, parser } = createParser()

      feed(parser, Buffer.concat([
        buildFrame({ opcode: opcodes.PING, payload: Buffer.from('p') }),
        buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('after') })
      ]))

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('after')
    })

    it('handles a close frame, replies to it and exposes the closing info', () => {
      const { handler, parser } = createParser()
      const closePayload = Buffer.alloc(2 + 3)
      closePayload.writeUInt16BE(1000, 0)
      closePayload.write('bye', 2)

      feed(parser, buildFrame({ opcode: opcodes.CLOSE, payload: closePayload }))

      expect(handler.readyState).toBe(states.CLOSING)
      expect(handler.closeState.has(1 /* SENT */)).toBe(true)
      expect(handler.closeState.has(2 /* RECEIVED */)).toBe(true)
      expect(parser.closingInfo).toEqual({ code: 1000, reason: 'bye', error: false })

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1000)

      // the socket must not be destroyed: the peer closes the connection
      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(handler.socket.destroy).not.toHaveBeenCalled()
    })

    it('stops parsing after a close frame', () => {
      const { handler, parser } = createParser()

      const callback = feed(parser, Buffer.concat([
        buildFrame({ opcode: opcodes.CLOSE, payload: Buffer.alloc(0) }),
        buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('ignored') })
      ]))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()
    })

    it('fails with 1002 when the close frame has a one byte body', () => {
      const { handler, parser } = createParser()

      feed(parser, buildFrame({ opcode: opcodes.CLOSE, payload: Buffer.from([0x03]) }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1002)
      expect(frames[0].payload.subarray(2).toString()).toBe('Received close frame with a 1-byte body.')
    })

    it('fails with 1002 when the close frame contains an invalid status code', () => {
      const { handler, parser } = createParser()
      const closePayload = Buffer.alloc(2)
      closePayload.writeUInt16BE(1005, 0)

      feed(parser, buildFrame({ opcode: opcodes.CLOSE, payload: closePayload }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1002)
      expect(frames[0].payload.subarray(2).toString()).toBe('Invalid status code')
    })

    it('fails with 1007 when the close reason is not valid UTF-8', () => {
      const { handler, parser } = createParser()
      const closePayload = Buffer.from([0x03, 0xe8, 0xc3, 0x28])

      feed(parser, buildFrame({ opcode: opcodes.CLOSE, payload: closePayload }))

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1007)
      expect(frames[0].payload.subarray(2).toString()).toBe('Invalid UTF-8')
    })
  })

  describe('write backpressure', () => {
    it('pauses parsing until the socket drains when the reply fills the buffer', () => {
      const handler = createHandler()
      handler.socket.writableNeedDrain = true
      const parser = new ByteParser(handler, null)

      const pingFrame = buildFrame({ opcode: opcodes.PING, payload: Buffer.from('p') })
      const callback = feed(parser, Buffer.concat([pingFrame, pingFrame]))

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.socket.listenerCount('drain')).toBe(1)
      expect(callback).not.toHaveBeenCalled()

      handler.socket.writableNeedDrain = false
      handler.socket.emit('drain')

      expect(handler.onPing).toHaveBeenCalledTimes(2)
      expect(callback).toHaveBeenCalledTimes(1)
    })

    it('does not resume parsing when the parser was destroyed before the drain event', () => {
      const handler = createHandler()
      handler.socket.writableNeedDrain = true
      const parser = new ByteParser(handler, null)

      const pingFrame = buildFrame({ opcode: opcodes.PING, payload: Buffer.from('p') })
      const callback = feed(parser, Buffer.concat([pingFrame, pingFrame]))

      expect(handler.onPing).toHaveBeenCalledTimes(1)

      parser.destroyed = true
      handler.socket.emit('drain')

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(callback).not.toHaveBeenCalled()
    })
  })

  describe('permessage-deflate', () => {
    function compressedExtensions () {
      return new Map([['permessage-deflate', '']])
    }

    it('decompresses a compressed text message', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.from('compressed payload'))

      const callback = feed(parser, buildFrame({
        opcode: opcodes.TEXT,
        rsv1: true,
        payload: compressed
      }))

      await nextTick()

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.TEXT)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('compressed payload')
      expect(handler.controller.abort).not.toHaveBeenCalled()
      expect(callback).toHaveBeenCalled()
    })

    it('decompresses an uncompressed frame when the extension is negotiated but RSV1 is clear', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())

      const callback = feed(parser, buildFrame({
        opcode: opcodes.TEXT,
        rsv1: false,
        payload: Buffer.from('plain payload')
      }))

      expect(callback).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('plain payload')
    })

    it('fails with 1007 when the compressed payload cannot be inflated', async () => {
      const { handler, parser } = createParser({}, compressedExtensions())
      const garbage = Buffer.from([0xff, 0xff, 0xff, 0xff, 0xff, 0xff])

      feed(parser, buildFrame({ opcode: opcodes.TEXT, rsv1: true, payload: garbage }))

      await nextTick()

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1007)
    })

    it('fails with 1009 when the decompressed message exceeds the payload limit', async () => {
      const { handler, parser } = createParser({ maxPayloadSize: 100 }, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x41))
      expect(compressed.length).toBeLessThanOrEqual(100)

      feed(parser, buildFrame({ opcode: opcodes.TEXT, rsv1: true, payload: compressed }))

      await nextTick()

      expect(handler.controller.abort).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      const frames = closeFramesWrittenTo(handler)
      expect(frames).toHaveLength(1)
      expect(frames[0].payload.readUInt16BE(0)).toBe(1009)
      expect(frames[0].payload.subarray(2).toString()).toBe('Max decompressed message size exceeded')
    })

    it('decompresses large payloads when the payload limit is disabled', async () => {
      const { handler, parser } = createParser({ maxPayloadSize: 0 }, compressedExtensions())
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x41))

      feed(parser, buildFrame({ opcode: opcodes.BINARY, rsv1: true, payload: compressed }))

      await nextTick()

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][0]).toBe(opcodes.BINARY)
      expect(handler.onMessage.mock.calls[0][1].length).toBe(1000)
      expect(handler.controller.abort).not.toHaveBeenCalled()
    })
  })
})
