it('fails the connection when RSV1 is set without permessage-deflate', () => {
  const { handler, parser } = createParser()

  feed(parser, buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('x'), rsv1: true }))

  expect(handler.controller.abort).toHaveBeenCalledTimes(1)
  expect(handler.onMessage).not.toHaveBeenCalled()

  const frames = closeFramesWrittenTo(handler)
  expect(frames).toHaveLength(1)
  expect(frames[0].payload.readUInt16BE(0)).toBe(1002)
  expect(frames[0].payload.subarray(2).toString()).toBe('Expected RSV1 to be clear.')
})

it.each([
  ['RSV2', { rsv2: true }],
  ['RSV3', { rsv3: true }]
])('fails the connection when %s is set', (_name, bits) => {
  const { handler, parser } = createParser()

  // give the parser a negotiated extension so only the RSV2/RSV3 check can
  // be responsible for the failure
  const extParser = new ByteParser(handler, new Map([['permessage-deflate', '']]))
  feed(extParser, buildFrame({ opcode: opcodes.TEXT, payload: Buffer.from('x'), ...bits }))

  expect(handler.controller.abort).toHaveBeenCalledTimes(1)
  expect(handler.onMessage).not.toHaveBeenCalled()

  const frames = closeFramesWrittenTo(handler)
  expect(frames).toHaveLength(1)
  expect(frames[0].payload.readUInt16BE(0)).toBe(1002)
  expect(frames[0].payload.subarray(2).toString()).toBe('RSV1, RSV2, RSV3 must be clear')
})

it('fails the connection when a control frame is fragmented', () => {
  const { handler, parser } = createParser()

  feed(parser, buildFrame({ opcode: opcodes.PING, fin: false, payload: Buffer.from('x') }))

  expect(handler.controller.abort).toHaveBeenCalledTimes(1)
  expect(handler.onPing).not.toHaveBeenCalled()

